-- Import master pegawai BPPKAD untuk modul perhitungan gaji
-- Sumber: docs/master/pns_bppkad.xls dan docs/master/pppk_bppkad.xls
-- Dibuat dari data yang sudah dipetakan ke tabel pegawai pada 2026-08-12.
-- Aman dijalankan ulang: UPDATE berdasarkan NIP, INSERT hanya untuk NIP yang belum ada.

START TRANSACTION;

SET @opd_bppkad_id := (
    SELECT id FROM master_opd
    WHERE nama_opd LIKE '%PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH%'
    LIMIT 1
);
SET @opd_bppkad_id := COALESCE(@opd_bppkad_id, 23);

SELECT 'BPPKAD_ES_2B', 'KEPALA BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH', 'STRUKTURAL', '2B', 1
WHERE NOT EXISTS (SELECT 1 FROM ref_jabatan WHERE nama_jabatan='KEPALA BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH');

SELECT 'BPPKAD_ES_3A', 'SEKRETARIS BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH', 'STRUKTURAL', '3A', 1
WHERE NOT EXISTS (SELECT 1 FROM ref_jabatan WHERE nama_jabatan='SEKRETARIS BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH');

SELECT 'BPPKAD_ES_3B', 'KEPALA BIDANG BPPKAD', 'STRUKTURAL', '3B', 1
WHERE NOT EXISTS (SELECT 1 FROM ref_jabatan WHERE nama_jabatan='KEPALA BIDANG BPPKAD');

SELECT 'BPPKAD_ES_4A', 'KEPALA SUBBAGIAN/SUBBIDANG BPPKAD', 'STRUKTURAL', '4A', 1
WHERE NOT EXISTS (SELECT 1 FROM ref_jabatan WHERE nama_jabatan='KEPALA SUBBAGIAN/SUBBIDANG BPPKAD');

SET @jab_bppkad_es_2b := (SELECT id FROM ref_jabatan WHERE nama_jabatan='KEPALA BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH' LIMIT 1);
SET @jab_bppkad_es_3a := (SELECT id FROM ref_jabatan WHERE nama_jabatan='SEKRETARIS BADAN PENDAPATAN, PENGELOLAAN KEUANGAN DAN ASET DAERAH' LIMIT 1);
SET @jab_bppkad_es_3b := (SELECT id FROM ref_jabatan WHERE nama_jabatan='KEPALA BIDANG BPPKAD' LIMIT 1);
SET @jab_bppkad_es_4a := (SELECT id FROM ref_jabatan WHERE nama_jabatan='KEPALA SUBBAGIAN/SUBBIDANG BPPKAD' LIMIT 1);

CREATE TEMPORARY TABLE tmp_import_pegawai_bppkad (
    nip VARCHAR(30) NOT NULL PRIMARY KEY,
    nama_lengkap VARCHAR(255) NOT NULL,
    jenis_kelamin ENUM('L','P') NULL,
    tgl_lahir DATE NULL,
    tgl_cpns DATE NULL,
    tgl_pns DATE NULL,
    jenis_kepegawaian ENUM('PNS','CPNS','PPPK','NON_ASN') NOT NULL,
    golongan VARCHAR(10) NULL,
    pangkat VARCHAR(100) NULL,
    status_pernikahan ENUM('BELUM_KAWIN','KAWIN','JANDA','DUDA') NULL,
    jumlah_anak TINYINT UNSIGNED NULL,
    terima_tunjangan_keluarga TINYINT(1) NOT NULL DEFAULT 1,
    masa_kerja_golongan TINYINT UNSIGNED NULL,
    tmt_kenaikan_pangkat DATE NULL,
    jabatan_eselon VARCHAR(10) NULL,
    ref_tpp_id INT NULL,
    persen_gaji TINYINT UNSIGNED NOT NULL DEFAULT 100,
    npwp VARCHAR(32) NULL
) ENGINE=Memory;


UPDATE pegawai p
JOIN tmp_import_pegawai_bppkad t ON t.nip=p.nip
SET p.nama_lengkap=t.nama_lengkap,
    p.jenis_kelamin=t.jenis_kelamin,
    p.tgl_lahir=t.tgl_lahir,
    p.tgl_cpns=t.tgl_cpns,
    p.tgl_pns=t.tgl_pns,
    p.status_kepegawaian='ASN',
    p.jenis_kepegawaian=t.jenis_kepegawaian,
    p.golongan=t.golongan,
    p.pangkat=t.pangkat,
    p.status_pernikahan=t.status_pernikahan,
    p.jumlah_anak=t.jumlah_anak,
    p.terima_tunjangan_keluarga=t.terima_tunjangan_keluarga,
    p.masa_kerja_golongan=t.masa_kerja_golongan,
    p.tmt_kenaikan_pangkat=t.tmt_kenaikan_pangkat,
    p.jabatan_struktural_id=CASE t.jabatan_eselon WHEN '2B' THEN @jab_bppkad_es_2b WHEN '3A' THEN @jab_bppkad_es_3a WHEN '3B' THEN @jab_bppkad_es_3b WHEN '4A' THEN @jab_bppkad_es_4a ELSE NULL END,
    p.jabatan_fungsional_id=NULL,
    p.jabatan_penatausahaan_id=NULL,
    p.kd_jabatan_fungsional=NULL,
    p.kd_tunjangan_khusus=NULL,
    p.ref_tpp_id=t.ref_tpp_id,
    p.persen_gaji=t.persen_gaji,
    p.npwp=t.npwp,
    p.opd_id=@opd_bppkad_id,
    p.is_active=1,
    p.updated_at=NOW();

SELECT t.nip,t.nama_lengkap,t.jenis_kelamin,t.tgl_lahir,t.tgl_cpns,t.tgl_pns,'ASN',t.jenis_kepegawaian,t.golongan,t.pangkat,t.status_pernikahan,t.jumlah_anak,t.terima_tunjangan_keluarga,t.masa_kerja_golongan,t.tmt_kenaikan_pangkat,
       CASE t.jabatan_eselon WHEN '2B' THEN @jab_bppkad_es_2b WHEN '3A' THEN @jab_bppkad_es_3a WHEN '3B' THEN @jab_bppkad_es_3b WHEN '4A' THEN @jab_bppkad_es_4a ELSE NULL END, t.ref_tpp_id, t.persen_gaji, t.npwp, @opd_bppkad_id, 1
FROM tmp_import_pegawai_bppkad t
LEFT JOIN pegawai p ON p.nip=t.nip
WHERE p.id IS NULL;

DROP TEMPORARY TABLE tmp_import_pegawai_bppkad;

COMMIT;

SELECT jenis_kepegawaian, COUNT(*) AS jumlah
FROM pegawai
WHERE opd_id=@opd_bppkad_id AND is_active=1 AND jenis_kepegawaian IN ('PNS','PPPK')
GROUP BY jenis_kepegawaian;

SELECT COUNT(*) AS missing_gapok
FROM pegawai p
WHERE p.opd_id=@opd_bppkad_id AND p.is_active=1 AND p.jenis_kepegawaian IN ('PNS','PPPK')
  AND NOT EXISTS (
      SELECT 1 FROM ref_gaji_pokok rg
      WHERE rg.jenis=p.jenis_kepegawaian AND rg.golongan=p.golongan
        AND rg.masa_kerja<=p.masa_kerja_golongan AND rg.is_active=1
  );
